create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,daily_target int not null default 80 check(daily_target between 1 and 100),created_at timestamptz default now());
create table public.task_categories(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,created_at timestamptz default now(),unique(user_id,name));
create table public.tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null check(length(trim(title))>0),description text,category text,priority text not null default 'Medium' check(priority in('High','Medium','Low')),status text not null default 'Pending' check(status in('Pending','In Progress','Completed','Rescheduled','Cancelled')),original_date date not null,scheduled_date date not null,original_deadline date,deadline date,estimated_minutes int not null default 0 check(estimated_minutes>=0),actual_minutes int not null default 0 check(actual_minutes>=0),completed_at timestamptz,reschedule_count int not null default 0 check(reschedule_count>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.task_subtasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,task_id uuid not null references public.tasks(id) on delete cascade,title text not null,completed boolean default false,created_at timestamptz default now());
create table public.task_reschedule_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,task_id uuid not null references public.tasks(id) on delete cascade,old_date date not null,new_date date not null,old_deadline date,new_deadline date,reason text not null,explanation text,action_plan text,rescheduled_at timestamptz not null default now());
create table public.task_status_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,task_id uuid not null references public.tasks(id) on delete cascade,old_status text,new_status text not null,changed_at timestamptz not null default now());
create table public.daily_reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,task_id uuid references public.tasks(id) on delete cascade,review_date date not null,reason text,explanation text,action_plan text,created_at timestamptz default now());
create table public.productivity_goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,period text not null default 'Weekly' check(period in('Daily','Weekly','Monthly','Yearly')),target numeric default 100,progress numeric default 0,created_at timestamptz default now());
create table public.habits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,created_at timestamptz default now());
create table public.habit_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,habit_id uuid not null references public.habits(id) on delete cascade,log_date date not null,created_at timestamptz default now(),unique(habit_id,log_date));
create table public.focus_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,task_id uuid references public.tasks(id) on delete set null,minutes int not null check(minutes>0),session_type text not null,created_at timestamptz default now());
create index on public.tasks(user_id,scheduled_date);create index on public.tasks(user_id,status);create index on public.task_reschedule_history(user_id,task_id);create index on public.task_status_history(user_id,changed_at);create index on public.habit_logs(user_id,log_date);
do $$ declare t text;begin foreach t in array array['profiles','task_categories','tasks','task_subtasks','task_reschedule_history','task_status_history','daily_reviews','productivity_goals','habits','habit_logs','focus_sessions'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy "owner access" on public.%I for all to authenticated using (%s) with check (%s)',t,case when t='profiles' then 'id = (select auth.uid())' else 'user_id = (select auth.uid())' end,case when t='profiles' then 'id = (select auth.uid())' else 'user_id = (select auth.uid())' end);end loop;end $$;
create function public.record_task_status() returns trigger language plpgsql security definer set search_path=public as $$begin if new.status is distinct from old.status then insert into public.task_status_history(user_id,task_id,old_status,new_status) values(new.user_id,new.id,old.status,new.status);end if;new.updated_at=now();return new;end$$;
create trigger task_status_audit before update on public.tasks for each row execute function public.record_task_status();
create function public.reschedule_task(p_task_id uuid,p_new_date date,p_new_deadline date,p_reason text,p_explanation text,p_action_plan text) returns void language plpgsql security invoker set search_path=public as $$declare t public.tasks%rowtype;begin select * into t from public.tasks where id=p_task_id and user_id=auth.uid() for update;if not found then raise exception 'Task not found';end if;if t.status in('Completed','Cancelled') then raise exception 'Cannot reschedule completed or cancelled task';end if;if p_new_date is null or length(trim(coalesce(p_reason,'')))=0 then raise exception 'Date and reason required';end if;insert into public.task_reschedule_history(user_id,task_id,old_date,new_date,old_deadline,new_deadline,reason,explanation,action_plan)values(auth.uid(),p_task_id,t.scheduled_date,p_new_date,t.deadline,p_new_deadline,p_reason,p_explanation,p_action_plan);insert into public.daily_reviews(user_id,task_id,review_date,reason,explanation,action_plan)values(auth.uid(),p_task_id,current_date,p_reason,p_explanation,p_action_plan);update public.tasks set scheduled_date=p_new_date,deadline=p_new_deadline,status='Rescheduled',reschedule_count=reschedule_count+1 where id=p_task_id and user_id=auth.uid();end$$;
revoke all on function public.reschedule_task(uuid,date,date,text,text,text) from public;grant execute on function public.reschedule_task(uuid,date,date,text,text,text) to authenticated;
